#!/usr/bin/env python3
"""Export open review items from the baked demo audits as a static remediation queue."""

from __future__ import annotations

import argparse
import json
from dataclasses import dataclass
from html import escape
from pathlib import Path
from urllib.parse import quote

from subpoena.api.review import audit_items
from subpoena.models import SEVERITY_RANK, AuditReport, Severity

DEFAULT_OUT = Path(__file__).resolve().parents[1] / "docs" / "demo"
DATA = DEFAULT_OUT / "data"

PAGE = """<!doctype html>
<!-- Generated by scripts/export_remediation_demo.py. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Remediation queue | Subpoena</title>
<style>
  :root {
    color-scheme: dark;
    --desk: #14161a; --panel: #1c1f26; --line: #2c313c; --ink: #e8e6df; --dim: #8b919e;
    --accent: #4f8cff;
    --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  }
  * { box-sizing: border-box; }
  body { margin: 0; background: var(--desk); color: var(--ink); font: 16px/1.5 var(--sans); }
  main { max-width: 76rem; margin: auto; padding: 1rem clamp(1rem, 4vw, 3rem) 3rem; }
  h1 { margin: .75rem 0; font-size: clamp(2rem, 6vw, 3.5rem); line-height: 1.1; }
  p { margin: 0 0 1.5rem; color: var(--dim); }
  a {
    display: inline-flex; align-items: center; min-height: 44px; min-width: 44px;
    max-width: 100%; color: var(--accent); text-underline-offset: .18em;
  }
  a:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
  table { width: 100%; table-layout: fixed; border-collapse: collapse; }
  th, td { padding: .625rem .75rem; text-align: left; overflow-wrap: anywhere; }
  th:first-child { width: 44%; }
  th:nth-child(2) { width: 21%; }
  th:nth-child(3) { width: 11%; }
  td { background: var(--panel); border-block: 1px solid var(--line); vertical-align: top; }
  td:last-child { padding-block: 0; }
  .label { display: none; }
  @media (max-width: 48rem) {
    table, tbody { display: block; }
    thead {
      position: absolute; width: 1px; height: 1px; padding: 0;
      overflow: hidden; clip-path: inset(50%); white-space: nowrap;
    }
    tr {
      display: block; margin-block: .75rem; padding: .625rem .875rem;
      background: var(--panel); border: 1px solid var(--line); border-radius: .65rem;
    }
    td { display: block; padding: .25rem 0; border: 0; }
    .label { display: block; color: var(--dim); }
  }
</style>
</head>
<body>
<main>
  <a href="hub.html#operations">Back to demo hub</a>
  <h1 id="queue-title">Remediation queue</h1>
  <p>These are the auditor’s suggested one-step fixes for open items in the demo audits.
    Each item’s resolution is unconfirmed.</p>
  <table role="table" aria-labelledby="queue-title">
    <thead role="rowgroup">
      <tr role="row">
        <th role="columnheader" scope="col">Suggested fix</th>
        <th role="columnheader" scope="col">Claim type</th>
        <th role="columnheader" scope="col">Severity</th>
        <th role="columnheader" scope="col">Scenario</th>
      </tr>
    </thead>
    <tbody role="rowgroup">
@ROWS@
    </tbody>
  </table>
</main>
</body>
</html>
"""

ROW = """      <tr role="row">
        <td role="cell"><span class="label" aria-hidden="true">Suggested fix</span>{fix}</td>
        <td role="cell"><span class="label" aria-hidden="true">Claim type</span>{claim_type}</td>
        <td role="cell"><span class="label" aria-hidden="true">Severity</span>{severity}</td>
        <td role="cell">
          <span class="label" aria-hidden="true">Scenario</span><a href="{href}">{title}</a>
        </td>
      </tr>"""


@dataclass(frozen=True)
class Remediation:
    fix: str
    claim_type: str
    severity: Severity
    status: str | None
    scenario_id: str
    scenario_title: str

    def html(self) -> str:
        # Match the viewer's encodeURIComponent hash routing.
        fragment = quote(self.scenario_id, safe="-_.!~*'()")
        return ROW.format(
            fix=escape(self.fix),
            claim_type=escape(self.claim_type),
            severity=escape(self.severity),
            href=escape(f"index.html#{fragment}"),
            title=escape(self.scenario_title),
        )


def open_remediations(data: Path) -> list[Remediation]:
    scenarios = {}
    for scenario in json.loads((data / "scenarios.json").read_bytes()):
        run = json.loads((data / f"run-{scenario['id']}.json").read_bytes())
        scenarios[run["audit_id"]] = scenario["id"], scenario["title"]

    rows = []
    for audit_file in sorted(data.glob("audit-*.json")):
        report = AuditReport.model_validate_json(audit_file.read_bytes())
        for item in audit_items(report):
            _, collection, index = item.result_pointer.split("/")
            if collection == "findings":
                result = report.findings[int(index)]
                claim_type, status = f"Finding · {result.kind}", None
            else:
                result = report.verdicts[int(index)]
                claim_type, status = result.claim.type, result.status
            rows.append(
                Remediation(
                    result.remediation or "No suggested fix recorded.",
                    claim_type,
                    result.severity,
                    status,
                    *scenarios[report.audit_id],
                )
            )

    # Findings have no verdict status and follow verdicts at the same severity.
    return sorted(
        rows,
        key=lambda row: (
            -SEVERITY_RANK[row.severity],
            row.status is None,
            row.status or "",
        ),
    )


def export(out: Path = DEFAULT_OUT) -> None:
    rows = "\n".join(row.html() for row in open_remediations(DATA))
    out.mkdir(parents=True, exist_ok=True)
    (out / "remediation.html").write_text(
        PAGE.replace("@ROWS@", rows), encoding="utf-8", newline="\n"
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--out", type=Path, default=DEFAULT_OUT, help="Demo output directory")
    export(parser.parse_args().out)
